import { useRouter } from "next/navigation";
import LabelChip from "./LabelChip";
import { LABEL_COLOR_CLASS, type LabelColor } from "@/lib/labelColors";

type Label = { id: string; name: string; color: string };

export default function LabelPicker({
  cardId,
  boardLabels,
  assigned,
}: {
  cardId: string;
  boardLabels: Label[];
  assigned: Label[];
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [, startTransition] = useTransition();
  const assignedIds = new Set(assigned.map((l) => l.id));

  async function toggle(label: Label) {
    if (assignedIds.has(label.id)) {
      await fetch(`/api/cards/${cardId}/labels/${label.id}`, { method: "DELETE" });
    } else {
      await fetch(`/api/cards/${cardId}/labels`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ labelId: label.id }),
      });
    }
    startTransition(() => router.refresh());
  }

  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap gap-1">
        {assigned.length === 0 ? (
          <span className="text-xs text-slate-400">ラベルなし</span>
        ) : (
          assigned.map((l) => (
            <LabelChip key={l.id} label={l} onRemove={() => toggle(l)} />
          ))
        )}
      </div>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="self-start rounded border border-slate-300 px-2 py-0.5 text-xs text-slate-700 hover:bg-slate-100"
      >
        {open ? "閉じる" : "ラベルを付与/解除"}
      </button>
      {open && (
        <div className="flex flex-col gap-1 rounded border border-slate-200 p-2">
          {boardLabels.length === 0 ? (
            <span className="text-xs text-slate-400">ボードにラベルがありません</span>
          ) : (
            boardLabels.map((l) => {
              const cls =
                LABEL_COLOR_CLASS[l.color as LabelColor] ?? "bg-slate-200 text-slate-800";
              return (
                <button
                  key={l.id}
                  type="button"
                  onClick={() => toggle(l)}
                  aria-pressed={assignedIds.has(l.id)}
                  className="flex items-center justify-between gap-2 rounded px-2 py-1 text-left text-xs hover:bg-slate-50"
                >
                  <span className={`rounded px-2 py-0.5 ${cls}`}>{l.name}</span>
                  <span className="text-slate-500">
                    {assignedIds.has(l.id) ? "付与済み ✓" : "付与"}
                  </span>
                </button>
              );
            })
          )}
        </div>
      )}
    </div>
  );
}

