// design/005_008_ui_features_ui.md § Molecule: LabelForm / spec/006
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import ColorPicker from "./ColorPicker";
import { LABEL_COLORS, type LabelColor } from "@/lib/labelColors";

type Label = { id: string; name: string; color: string };

export default function LabelForm({
  boardId,
  label,
  onDone,
}: {
  boardId: string;
  label?: Label;
  onDone?: () => void;
}) {
  const router = useRouter();
  const [name, setName] = useState(label?.name ?? "");
  const [color, setColor] = useState<LabelColor>(
    (label?.color as LabelColor) ?? LABEL_COLORS[0],
  );
  const [error, setError] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const url = label ? `/api/labels/${label.id}` : `/api/boards/${boardId}/labels`;
    const res = await fetch(url, {
      method: label ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, color }),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      setError(body?.error?.message ?? "保存に失敗しました");
      return;
    }
    if (!label) setName("");
    onDone?.();
    startTransition(() => router.refresh());
  }

  return (
    <form onSubmit={submit} className="flex flex-col gap-2">
      <input
        type="text"
        aria-label="ラベル名"
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="ラベル名（1〜50文字）"
        className="rounded border border-slate-300 px-2 py-1 text-sm focus:border-slate-500 focus:outline-none"
      />
      <ColorPicker value={color} onChange={setColor} />
      {error && <p className="text-xs text-red-600">{error}</p>}
      <button
        type="submit"
        className="self-start rounded bg-slate-900 px-3 py-1 text-xs font-medium text-white hover:bg-slate-700"
      >
        {label ? "更新" : "ラベル作成"}
      </button>
    </form>
  );
}

