// design/005_008_ui_features_ui.md § Organism: LabelManager / spec/006
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import LabelForm from "./LabelForm";
import LabelChip from "./LabelChip";

type Label = { id: string; name: string; color: string };

export default function LabelManager({
  boardId,
  boardLabels,
}: {
  boardId: string;
  boardLabels: Label[];
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  async function remove(labelId: string) {
    if (!confirm("このラベルを削除します。付与済みも解除されます。")) return;
    await fetch(`/api/labels/${labelId}`, { method: "DELETE" });
    startTransition(() => router.refresh());
  }

  return (
    <div>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="rounded border border-slate-300 px-3 py-1.5 text-sm text-slate-700 hover:bg-slate-100"
      >
        {open ? "ラベル管理を閉じる" : "ラベル管理"}
      </button>
      {open && (
        <div className="mt-3 rounded-lg border border-slate-200 bg-white p-4">
          <h3 className="mb-2 text-sm font-semibold text-slate-700">ラベルを追加</h3>
          <LabelForm boardId={boardId} />
          <h3 className="mt-4 mb-2 text-sm font-semibold text-slate-700">
            ラベル一覧（{boardLabels.length}）
          </h3>
          {boardLabels.length === 0 ? (
            <p className="text-xs text-slate-400">まだラベルがありません</p>
          ) : (
            <ul className="flex flex-col gap-2">
              {boardLabels.map((l) => (
                <li key={l.id} className="flex flex-col gap-2 border-b border-slate-100 pb-2">
                  <div className="flex items-center justify-between gap-2">
                    <LabelChip label={l} />
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() => setEditing(editing === l.id ? null : l.id)}
                        className="rounded border border-slate-300 px-2 py-0.5 text-xs text-slate-700 hover:bg-slate-100"
                      >
                        編集
                      </button>
                      <button
                        type="button"
                        onClick={() => remove(l.id)}
                        className="rounded border border-red-300 px-2 py-0.5 text-xs text-red-700 hover:bg-red-50"
                      >
                        削除
                      </button>
                    </div>
                  </div>
                  {editing === l.id && (
                    <LabelForm boardId={boardId} label={l} onDone={() => setEditing(null)} />
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

