"use client";

// design/005_008_ui_features_ui.md § Molecule: DueDateField / spec/007
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import DueDateBadge, { formatDueDate } from "./DueDateBadge";

export default function DueDateField({
  cardId,
  dueDate,
}: {
  cardId: string;
  dueDate: string | null;
}) {
  const router = useRouter();
  const [value, setValue] = useState(dueDate ? formatDueDate(dueDate) : "");
  const [error, setError] = useState<string | null>(null);
  const [, startTransition] = useTransition();

  async function save(next: string | null) {
    setError(null);
    const res = await fetch(`/api/cards/${cardId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dueDate: next }),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      setError(body?.error?.message ?? "期限の更新に失敗しました");
      return;
    }
    startTransition(() => router.refresh());
  }

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        {dueDate ? (
          <DueDateBadge dueDate={dueDate} />
        ) : (
          <span className="text-xs text-slate-400">期限なし</span>
        )}
      </div>
      <div className="flex items-center gap-2">
        <input
          type="date"
          aria-label="期限"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          className="rounded border border-slate-300 px-2 py-1 text-sm focus:border-slate-500 focus:outline-none"
        />
        <button
          type="button"
          onClick={() => save(value || null)}
          className="rounded bg-slate-900 px-3 py-1 text-xs font-medium text-white hover:bg-slate-700"
        >
          期限を保存
        </button>
        {dueDate && (
          <button
            type="button"
            onClick={() => {
              setValue("");
              save(null);
            }}
            className="rounded border border-slate-300 px-3 py-1 text-xs text-slate-700 hover:bg-slate-100"
          >
            解除
          </button>
        )}
      </div>
      {error && <p className="text-xs text-red-600">{error}</p>}
    </div>
  );
}
